// Generates the TypeScript half of the canonical model from contracts/.
//
// The Go half is generated by contracts/tools from the same JSON Schema files,
// which is the entire point of contracts/: the duplication this repository is
// trying to remove is cross-language, and no amount of refactoring inside
// either language can remove it.
//
// Usage, from the repository root:
//
//   node frontend/scripts/generate-protocol-types.mjs <schema.json>...
//
// The schema list comes from contracts/codegen.mk so that make, the Go
// generator and this script all work from one enumeration of the model.

import { mkdir, writeFile } from "node:fs/promises";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { compile } from "json-schema-to-typescript";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(join(here, "..", ".."));
const outFile = join(repoRoot, "frontend", "src", "protocol", "generated", "index.ts");

const schemas = process.argv.slice(2);
if (schemas.length === 0) {
  console.error("generate-protocol-types: no schema files given");
  process.exit(1);
}

// Every schema is compiled as one unit rather than one file each. Compiling
// them separately inlines each shared type — Merchant, Amount, PublicKey — into
// every file that references it, and the frontend ends up with several
// structurally identical Merchant types that TypeScript is happy to keep apart.
//
// One synthetic root whose $defs point at every schema gives the opposite:
// json-schema-to-typescript hoists each $def into its own exported interface,
// declared once and referenced by name from everywhere else.
//
// This only holds while every $ref is bare. A sibling keyword next to a $ref —
// a description, an annotation — makes the referring schema a distinct object,
// and a second copy of the referenced type is emitted as `Merchant1`. Keep
// per-field prose in the parent's $comment instead.
const root = {
  $schema: "https://json-schema.org/draft/2020-12/schema",
  title: "Contracts",
  $defs: Object.fromEntries(
    schemas.map((path) => [path, { $ref: relative(repoRoot, resolve(path)) }]),
  ),
};

const banner = [
  "/* eslint-disable */",
  "/**",
  " * Code generated from contracts/ by frontend/scripts/generate-protocol-types.mjs.",
  " * DO NOT EDIT — change the JSON Schema and run `make generate` from the repository root.",
  " */",
].join("\n");

const ts = await compile(root, "Contracts", {
  cwd: repoRoot + "/",
  bannerComment: banner,
  declareExternallyReferenced: true,
  unreachableDefinitions: true,
  additionalProperties: false,
  strictIndexSignatures: true,
  $refOptions: { resolve: { http: false } },
});

// The synthetic root carries no information — it exists only to pull the
// schemas into a single compilation unit.
const withoutRoot = ts.replace(/export interface Contracts \{[\s\S]*?\n\}\n/, "");

await mkdir(dirname(outFile), { recursive: true });
await writeFile(outFile, withoutRoot, "utf8");

console.log(
  `generate-ts: ${schemas.length} schemas -> ${relative(repoRoot, outFile)}`,
);
